import numpy as np

rng = np.random.default_rng(0)

def softmax(z):
    # 10個の点数を「合計1の確率」に変える（Lv31と同じ）
    e = np.exp(z - z.max(axis=1, keepdims=True))
    return e / e.sum(axis=1, keepdims=True)

def init():
    # 脳の重み：入力35 → 中間32 → 出力10
    return {"W1": rng.normal(0, 0.3, (35, 32)), "b1": np.zeros(32),
            "W2": rng.normal(0, 0.3, (32, 10)), "b2": np.zeros(10)}

def step(P, X, y, lr):
    # 渡された絵で1回だけ「予想 → 逆伝播 → 更新」をする（Lv18で作ったもの）
    Y = np.eye(10)[y]
    h = np.maximum(0, X @ P["W1"] + P["b1"])
    p = softmax(h @ P["W2"] + P["b2"])
    d2 = (p - Y) / len(X)
    d1 = (d2 @ P["W2"].T) * (h > 0)
    P["W2"] -= lr * (h.T @ d2);  P["b2"] -= lr * d2.sum(axis=0)
    P["W1"] -= lr * (X.T @ d1);  P["b1"] -= lr * d1.sum(axis=0)

def train(X, y):
    P = init()
    for epoch in range(30):
        order = rng.permutation(len(X))
        for i in range(0, len(X), 32):
            idx = order[i:i + 32]
            step(P, X[idx], y[idx], 0.1)
    return P

