import numpy as np

def similarity(a, b):
    return (a @ b) / (np.linalg.norm(a) * np.linalg.norm(b))

def nearest(word, vectors):
    best_word = ""
    best_sim = -1
    for w in vectors:
        if w == word:
            continue
        sim = similarity(vectors[word], vectors[w])
        if sim > best_sim:
            best_sim = sim
            best_word = w
